 "No alargar": "Ne pas traîner",
 "<b style=\"font-size:25px;color:#9a4fb8\">No alargar</b><br><span style=\"font-size:21px;color:#33260a\">Decidir con agilidad.</span>": "<b style=\"font-size:25px;color:#9a4fb8\">Ne pas traîner</b><br><span style=\"font-size:21px;color:#33260a\">Décider avec rapidité.</span>",
 "Cumplir las reglas": "Respecter les règles",
 "<b style=\"font-size:25px;color:#ca6e1c\">Cumplir las reglas</b><br><span style=\"font-size:21px;color:#33260a\">Pregunta en lugar de suponer.</span>": "<b style=\"font-size:25px;color:#ca6e1c\">Respecter les règles</b><br><span style=\"font-size:21px;color:#33260a\">Demande au lieu de supposer.</span>",
