 "<b style=\"font-size:26px;color:#d17a29\">Un gasto médico</b><br><span style=\"font-size:21px;color:#13203b\">Dentista, gafas, medicinas.</span>": "<b style=\"font-size:26px;color:#d17a29\">Une dépense médicale</b><br><span style=\"font-size:21px;color:#13203b\">Dentiste, lunettes, médicaments.</span>",
